
const COLUMNS=['Cardinal','Fixed','Mutable']; const SEASONS={north:['Spring','Summer','Autumn','Winter'],south:['Autumn','Winter','Spring','Summer']}; const ELEMENT_CLASS={Fire:'element-fire',Water:'element-water',Air:'element-air',Earth:'element-earth'}; const TEXT_SIGNS={Aries:'♈︎',Taurus:'♉︎',Gemini:'♊︎',Cancer:'♋︎',Leo:'♌︎',Virgo:'♍︎',Libra:'♎︎',Scorpio:'♏︎',Sagittarius:'♐︎',Capricorn:'♑︎',Aquarius:'♒︎',Pisces:'♓︎'};
