const TONIC_INTERVALS=[{name:'All notes / complete field',step:'all',note:'C through B',fraction:'complete chromatic field',meaning:'The whole field is lit at once so the viewer can see every tone relationship before isolating one interval.'},{name:'Root / tonic',step:0,note:'C',fraction:'zero steps / return point',meaning:'The tonic is the return point: home, octave logic, and resolution.'},{name:'Minor second',step:1,note:'C sharp / D flat',fraction:'one twelfth of the circle',meaning:'The closest chromatic neighbor. Maximum nearness, high friction, and immediate pull.'},{name:'Major second',step:2,note:'D',fraction:'one sixth of the circle',meaning:'A whole-step relationship: movement, adjacency, and melodic opening.'},{name:'Minor third',step:3,note:'D sharp / E flat',fraction:'one fourth of the circle',meaning:'A three-step relation with inward color, shadow, and minor-triad feeling.'},{name:'Major third',step:4,note:'E',fraction:'one third of the circle',meaning:'Bright triadic relation: tone becomes stable, consonant, and declarative.'},{name:'Perfect fourth',step:5,note:'F',fraction:'five twelfths of the circle',meaning:'A threshold interval: stable enough to stand, unresolved enough to lean.'},{name:'Tritone',step:6,note:'F sharp / G flat',fraction:'one half of the circle',meaning:'The central split of the octave: tension, mirror, crossing, and inversion.'},{name:'Perfect fifth',step:7,note:'G',fraction:'seven twelfths of the circle',meaning:'The strongest outward consonance after the octave: support, relation, and harmonic anchoring.'},{name:'Minor sixth',step:8,note:'G sharp / A flat',fraction:'two thirds of the circle',meaning:'A soft expansion of the minor field: sweetness, ache, and resonance.'},{name:'Major sixth',step:9,note:'A',fraction:'three fourths of the circle',meaning:'Open consonance with lift, breadth, and songlike extension.'},{name:'Minor seventh',step:10,note:'A sharp / B flat',fraction:'five sixths of the circle',meaning:'A near-return that still asks to resolve: pressure before home.'},{name:'Major seventh',step:11,note:'B',fraction:'eleven twelfths of the circle',meaning:'The closest approach before return: longing, leading tone, and unfinished arrival.'},{name:'Octave',step:12,note:'C',fraction:'full circle / return',meaning:'The tonic returns at a higher register. The cycle completes without losing identity.'}];
const ANCIENT_METHODS=[{title:'Divided circle',detail:'Babylonian and zodiacal practice divide the wheel into signs, degrees, and equal arcs so that relationship is measured by separation on the circle.'},{title:'Gnomon and shadow',detail:'Egyptian and later Mediterranean sky-watching used the upright rod and its shadow to teach angle, noon, season, and orientation.'},{title:'Monochord and harmonic ratio',detail:'Greek harmonic teaching used the string, the monochord, and whole-number ratios to show that relation can be heard as well as seen.'},{title:'Rope-stretching and survey',detail:'Measured cords, cubits, and stretched lines gave ancient builders a practical grammar for rightness, boundary, and repeated interval.'},{title:'Pendulum measure',detail:'One teaching line associated with Egypt links a pendulum of about one meter to a beat of about one second per half swing. It gives a memorable bridge between length, rhythm, and periodic time.'}];
