const ANCIENT_ACTIVITIES=[{title:'Wheel cross',detail:'Make a cross from two rulers, set a protractor or wheel at the center, and hang a plumb line or weight to measure sky angles.'},{title:'Gnomon and shadow',detail:'Drag the Sun through the sky and watch the upright rod cast different shadows. This teaches angle, noon, season, and orientation.'},{title:'Monochord',detail:'Move a bridge along a string to divide its length and hear how ratio becomes interval. This links measure to music.'},{title:'Pendulum',detail:'Change the pendulum length and watch the swing period change. This teaches the bridge between length and periodic time.'},{title:'Rope-stretching',detail:'Drag pegs to stretch measured cords into triangles, right angles, and survey frames. This teaches practical geometry.'},{title:'Cubit and body measure',detail:'Compare body-based units with constructed units so proportion stays tied to the body as well as the abstract line.'}];
